<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api'
import type { AdminItem, Category, Page, TicketDetail, TicketSummary } from '../types'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(),loading=ref(false),rows=ref<TicketSummary[]>([]),total=ref(0),detail=ref<TicketDetail|null>(null),drawer=ref(false),assignees=ref<AdminItem[]>([]),categories=ref<Category[]>([])
const query=reactive({keyword:'',status:'',page:1,pageSize:20}),assignId=ref(''),reply=ref(''),target=ref(''),reason=ref('')
const faqForm=reactive({categoryId:'',title:'',question:'',answer:''})
const nextStatuses=computed(()=>{const s=detail.value?.status;return s==='PROCESSING'?['WAITING_USER','RESOLVED']:s==='WAITING_USER'?['PROCESSING','RESOLVED']:s==='RESOLVED'?['CLOSED']:[]})
async function load(){loading.value=true;try{const p=await api.get<Page<TicketSummary>>('/tickets',query);rows.value=p.items;total.value=p.total}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}
async function open(row:TicketSummary){drawer.value=true;const result=await api.get<TicketDetail>(`/tickets/${row.id}`);detail.value=result;assignId.value=result.assigneeId||'';faqForm.title=result.title;faqForm.question=result.description;faqForm.answer=result.resolution||''}
async function assign(){if(!detail.value||!assignId.value)return;try{detail.value=await api.post(`/tickets/${detail.value.id}/assign`,{assigneeId:assignId.value},detail.value.version);ElMessage.success('分配成功');load()}catch(e){ElMessage.error((e as Error).message)}}
async function sendReply(){if(!detail.value||!reply.value.trim())return;try{detail.value=await api.post(`/tickets/${detail.value.id}/replies`,{content:reply.value,attachmentIds:[]});reply.value='';ElMessage.success('回复成功')}catch(e){ElMessage.error((e as Error).message)}}
async function transition(){if(!detail.value||!target.value||!reason.value.trim())return;try{detail.value=await api.post(`/tickets/${detail.value.id}/transitions`,{targetStatus:target.value,reason:reason.value},detail.value.version);target.value='';reason.value='';ElMessage.success('状态已更新');load()}catch(e){ElMessage.error((e as Error).message)}}
async function convertFaq(){if(!detail.value||!faqForm.categoryId||!faqForm.answer)return;try{await api.post(`/tickets/${detail.value.id}/convert-to-faq`,faqForm);ElMessage.success('已创建 FAQ 草稿')}catch(e){ElMessage.error((e as Error).message)}}
onMounted(async()=>{await load();try{assignees.value=await api.get('/tickets/assignees');categories.value=await api.get('/faq-categories')}catch{}})
</script>
<template><div><div class="page-heading"><div><h2>工单管理</h2><p>处理用户留言、分配客服并跟踪状态</p></div></div><div class="panel toolbar"><el-input v-model="query.keyword" clearable placeholder="工单编号、标题或联系方式" @keyup.enter="load"/><el-select v-model="query.status" clearable placeholder="全部状态" style="width:180px"><el-option v-for="s in ['PENDING','PROCESSING','WAITING_USER','RESOLVED','CLOSED']" :key="s" :label="s" :value="s"/></el-select><el-button type="primary" @click="query.page=1;load()">查询</el-button><el-button @click="query.keyword='';query.status='';load()">重置</el-button></div><div class="panel table-panel"><el-table v-loading="loading" :data="rows" stripe @row-click="open"><el-table-column prop="id" label="工单编号" width="180"/><el-table-column prop="title" label="标题" min-width="220" show-overflow-tooltip/><el-table-column prop="customerName" label="用户" width="120"/><el-table-column prop="category" label="分类" width="120"/><el-table-column prop="assigneeName" label="负责人" width="120"/><el-table-column label="状态" width="140"><template #default="{row}"><el-tag class="status-tag" effect="light">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="190"/></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" layout="total,prev,pager,next" :total="total" @change="load"/></div></div><el-drawer v-model="drawer" size="min(720px,96vw)" title="工单详情"><div v-if="detail" style="padding:0 22px 28px"><div class="detail-grid"><div class="detail-item"><small>工单编号</small>{{detail.id}}</div><div class="detail-item"><small>状态</small>{{detail.status}}</div><div class="detail-item"><small>用户 / 联系方式</small>{{detail.customerName}} · {{detail.contact}}</div><div class="detail-item"><small>设备</small>{{detail.deviceBrand}} {{detail.deviceModel}}</div></div><h3>{{detail.title}}</h3><p style="line-height:1.8;color:#52647d">{{detail.description}}</p><el-divider>处理操作</el-divider><div style="display:flex;gap:10px"><el-select v-model="assignId" placeholder="选择客服" style="flex:1"><el-option v-for="a in assignees" :key="a.id" :label="`${a.name} (${a.account})`" :value="a.id"/></el-select><el-button type="primary" :disabled="detail.status!=='PENDING'" @click="assign">分配</el-button></div><div v-if="nextStatuses.length" style="display:grid;grid-template-columns:180px 1fr auto;gap:10px;margin-top:12px"><el-select v-model="target" placeholder="目标状态"><el-option v-for="s in nextStatuses" :key="s" :label="s" :value="s"/></el-select><el-input v-model="reason" placeholder="流转原因/解决方案"/><el-button @click="transition">更新状态</el-button></div><el-divider>沟通记录</el-divider><div class="conversation"><div v-for="r in detail.replies" :key="r.id" class="reply" :class="{admin:r.senderType==='admin'}"><small>{{r.senderName}} · {{r.createdAt}}</small>{{r.content}}</div></div><div style="display:flex;gap:10px;margin-top:14px"><el-input v-model="reply" type="textarea" :rows="2" placeholder="输入回复内容"/><el-button type="primary" :disabled="!['PROCESSING','WAITING_USER'].includes(detail.status)" @click="sendReply">回复</el-button></div><template v-if="auth.isAdmin&&['RESOLVED','CLOSED'].includes(detail.status)"><el-divider>转换为 FAQ 草稿</el-divider><el-select v-model="faqForm.categoryId" placeholder="FAQ 分类" style="width:100%;margin-bottom:10px"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-input v-model="faqForm.title" placeholder="标题" style="margin-bottom:10px"/><el-input v-model="faqForm.question" type="textarea" :rows="2" placeholder="问题" style="margin-bottom:10px"/><el-input v-model="faqForm.answer" type="textarea" :rows="4" placeholder="答案"/><el-button type="primary" style="margin-top:10px" @click="convertFaq">创建草稿</el-button></template></div></el-drawer></div></template>
